INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Elected president for the PRN in 1989 and stayed in the party until 2000, when he joined the PRTB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 1 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Elegido presidente por el PRN en 1989, permaneció en el partido hasta 2000, cuando se afilió al PRTB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 1 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Party whose 1989 campaign funds were formally administered by Cláudio Vieira, according to his testimony to the CPMI. The party itself was not formally accused in the case.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 2 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Partido cuyos fondos de campaña de 1989 eran administrados formalmente por Cláudio Vieira, según su declaración ante la CPMI. El partido en sí no fue objeto de acusación formal en el caso.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 2 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Removed from office on 2 October 1992, after the Chamber authorised the proceedings by 441 votes to 38. He resigned on 29 December and, the following day, the Senate barred him from public office for eight years by 76 votes to 2, a result later upheld by the Supreme Federal Court (STF).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 3 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Apartado del cargo el 2 de octubre de 1992, después de que la Cámara autorizara el proceso por 441 votos a 38. Dimitió el 29 de diciembre y, al día siguiente, el Senado lo inhabilitó durante ocho años por 76 votos a 2, resultado ratificado después por el Supremo Tribunal Federal (STF).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 3 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPMI, the president''s personal expenses were paid with money from the scheme, including deposits into the account of his secretary Ana Acioli and a "ghost" cheque used to buy a Fiat Elba. Collor gave a speech denying the statements of the driver Eriberto França and was acquitted by the STF in 1994.', NULL, 'Estimate from the time for 33 months of the term of office, cited in the context of the CPMI report; amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 4 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la CPMI, los gastos personales del presidente se pagaron con fondos de la trama, incluidos depósitos en la cuenta de la secretaria Ana Acioli y un cheque fantasma utilizado para comprar un Fiat Elba. Collor hizo un pronunciamiento negando las declaraciones del chófer Eriberto França y fue absuelto por el STF en 1994.', NULL, 'Estimación de la época para 33 meses de mandato, citada en el contexto del informe de la CPMI; importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 4 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Tried by the STF in 1994 on a charge of passive corruption linked to the scheme, he was acquitted by 5 votes to 3 for lack of evidence of his involvement.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 5 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Juzgado por el STF en 1994 por cohecho pasivo vinculado a la trama, fue absuelto por 5 votos a 3 por falta de pruebas de su implicación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 5 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In Criminal Case 465 (AP 465), a case separate from the 1994 one, the Federal Prosecution Service (MPF) accused him of receiving bribes from advertising companies in exchange for government contracts. The STF acquitted him for insufficient evidence, and three justices considered the passive corruption and false-statement charges time-barred.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 6 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la Acción Penal 465 (AP 465), distinta de la de 1994, el MPF lo acusó de recibir sobornos de empresas de publicidad a cambio de contratos del Gobierno. El STF lo absolvió por insuficiencia de pruebas, y tres magistrados consideraron prescritos el cohecho pasivo y la falsedad documental.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 6 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was treasurer of Collor''s campaigns for governor of Alagoas in 1986 and for the Presidency in 1989, after being introduced to him by the sugar-mill owner João Lyra.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 7 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fue tesorero de las campañas de Collor al Gobierno de Alagoas, en 1986, y a la Presidencia, en 1989, tras serle presentado por el empresario azucarero João Lyra.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 7 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Unanimously sentenced by the STF to seven years in prison in the semi-open regime, plus a fine, for false statements in documents (falsidade ideológica) linked to the ghost accounts, after confessing that the idea of the accounts had been his. The defence, led by Nabor Bulhões, unsuccessfully asked for confession to be treated as a mitigating factor.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 8 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por unanimidad por el STF a siete años de prisión en régimen semiabierto, más multa, por falsedad documental vinculada a las cuentas fantasma, tras confesar que la idea de las cuentas había sido suya. La defensa, de Nabor Bulhões, pidió sin éxito la atenuante de confesión.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 8 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He fled the country after a pre-trial detention order was issued in 1993 and was captured in Thailand. In 1994 he was sentenced by the 10th Federal Court in Brasília to four years for tax evasion, had his habeas corpus petition rejected by the Superior Court of Justice (STJ), and the case ended in 1998 with the extinction of liability on his death.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 9 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Huyó del país tras dictarse su prisión preventiva en 1993 y fue capturado en Tailandia. En 1994 fue condenado por el Juzgado Federal 10.º de Brasilia a cuatro años por evasión fiscal, el Superior Tribunal de Justicia (STJ) denegó su habeas corpus, y el proceso terminó en 1998 con la extinción de la responsabilidad penal por su muerte.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 9 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He owned Brasil Jet, an air-taxi company that, according to the driver Eriberto França, paid bills for the Casa da Dinda.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 10 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Era dueño de Brasil Jet, empresa de taxi aéreo que, según el chófer Eriberto França, pagaba cuentas de la Casa da Dinda.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 10 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPMI concluded in August 1992 that the refurbishment of the Casa da Dinda, Collor''s residence, was paid for by Brasil Jet. No specific court decision about the company was found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 11 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La CPMI concluyó en agosto de 1992 que la reforma de la Casa da Dinda, residencia de Collor, fue pagada por Brasil Jet. No se localizó ninguna decisión judicial específica sobre la empresa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 11 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The president''s private secretary and official treasurer of the 1989 campaign before the Superior Electoral Court (TSE). He told the CPMI that he had not received warnings about PC Farias from Pedro Collor and that he would not take unsubstantiated accusations to the president.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 12 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Secretario particular del presidente y tesorero oficial de la campaña de 1989 ante el Tribunal Superior Electoral (TSE). Ante la CPMI negó haber recibido advertencias de Pedro Collor sobre PC Farias y dijo que no llevaría al presidente acusaciones sin pruebas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 12 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Together with the businessman Luiz Estevão, he presented to the CPMI, as a legitimate loan, documents for an alleged US$ 4 million Uruguayan financing of the 1989 campaign, the so-called Operation Uruguay (Operação Uruguai). Years later, the Federal Revenue Service concluded that the operation was a sham.', NULL, 'Figure from the Gazeta do Povo; the Correio da Manhã gives US$ 3.75 million. Amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 13 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Junto con el empresario Luiz Estevão, presentó a la CPMI, como préstamo legítimo, documentos de una supuesta financiación uruguaya de 4 millones de dólares para la campaña de 1989, la llamada Operación Uruguay. Años después, la Receita Federal (Hacienda) concluyó que la operación fue una farsa.', NULL, 'Cifra de la Gazeta do Povo; el Correio da Manhã cita 3,75 millones de dólares. Importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 13 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was a member of the PFL while serving as general rapporteur of the Budget; the 2006 Estadão retrospective lists him as PPR-BA at the time of his resignation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 14 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Estaba afiliado al PFL cuando ejercía de relator general del Presupuesto; el balance de Estadão de 2006 lo registra como PPR-BA en el momento de su renuncia.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 14 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
