INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPI''s banking sub-committee, he moved almost US$ 2 million between 1989 and 1993, an amount considered incompatible with his salary; the deputy''s position is not given in the article.', NULL, 'Approximate amount in US dollars established by the CPI, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 19 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la subcomisión de bancos de la CPI, movió casi 2 millones de dólares entre 1989 y 1993, importe considerado incompatible con su salario; la postura del diputado no consta en el reportaje.', NULL, 'Importe aproximado en dólares determinado por la CPI, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 19 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPI, he passed US$ 35,000 to Ibsen in three named cheques, half of the US$ 70,000 deposited in his account at Banco Cidade; Ibsen denied involvement, and the criminal case against him was closed.', NULL, 'Amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 20 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la CPI, transfirió 35.000 dólares a Ibsen en tres cheques nominativos, la mitad de los 70.000 dólares depositados en su cuenta del Banco Cidade; Ibsen negó su implicación, y la causa penal contra él se archivó.', NULL, 'Importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 20 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He presided over the Chamber between 1991 and 1993 and served four terms as federal deputy for the PMDB in Rio Grande do Sul.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 21 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidió la Cámara entre 1991 y 1993 y ejerció cuatro mandatos como diputado federal por el PMDB de Rio Grande do Sul.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 21 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was stripped of his seat on 18 May 1994, by 296 votes to 139, and has always denied the accusations; in 2004, the Veja reporter admitted that the published figure of US$ 1 million was in fact US$ 1,000.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 22 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
