INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Removed from the project on 27 May 1995 by presidential decision after the INSS issued a tax assessment against it and there were signs of forged payment slips, it was declared bankrupt on 21 July 1995; a Chamber committee recorded that the irregularity appeared to have occurred without the management''s intent.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 51 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Apartada del proyecto el 27 de mayo de 1995 por decisión presidencial tras una infracción levantada por el INSS e indicios de guías falsificadas, fue declarada en quiebra el 21 de julio de 1995; una comisión de la Cámara registró que la irregularidad parecía haberse producido sin intención de la dirección.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 51 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
