INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He acted as Raytheon''s commercial representative in Brazil; the company described him as an independent representative with no power to sign contracts on its behalf.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 53 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Actuaba como representante comercial de Raytheon en Brasil; la empresa lo describió como representante independiente, sin poderes para firmar contratos en su nombre.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 53 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In conversations in September 1995 recorded by the Federal Police, he asked the ambassador to intercede with the presidential palace to unblock the Sivam in the Senate; to the Senate committee, he said that his remark that there was no one left to give money meant that corruption had come to an end.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 54 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En conversaciones de septiembre de 1995 grabadas por la Policía Federal, pidió al embajador que intercediera ante el Planalto para desbloquear el Sivam en el Senado; ante la comisión del Senado, dijo que su frase sobre que ya no había quien diera dinero significaba que la corrupción se había acabado.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 54 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Chamber CPI found signs of administrative advocacy (advocacia administrativa), influence peddling and active corruption involving the businessman and sent its report to the Federal Prosecution Service (MPF); Assumpção suggested the tapes may have been tampered with.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 55 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La CPI de la Cámara apuntó indicios de abogacía administrativa, tráfico de influencias y cohecho activo en relación con el empresario y remitió el informe al MPF; Assumpção sugirió que las cintas podían haber sido manipuladas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 55 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Head of Presidential Protocol, he had his home telephone tapped by the Federal Police and, in the conversations, promised to approach officials about the Sivam; dismissed on 17 November 1995, he denied having lobbied and challenged the integrity of the tapes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 56 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Jefe del Ceremonial de la Presidencia, tuvo el teléfono de su casa intervenido por la Policía Federal y, en las conversaciones, prometió consultar a autoridades sobre el Sivam; cesado el 17 de noviembre de 1995, negó haber hecho lobby y cuestionó la integridad de las cintas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 56 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He travelled to the USA on 22 September 1995 on an aircraft belonging to the owner of Líder; the Itamaraty (Foreign Ministry) concluded that the flight was to bring the businessman back from Miami and that the ambassador paid his own travel expenses.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 57 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Viajó a Estados Unidos el 22 de septiembre de 1995 en una aeronave del dueño de Líder; el Itamaraty (Ministerio de Asuntos Exteriores) concluyó que el vuelo iba a recoger al empresario de vuelta de Miami y que el embajador pagó sus gastos de viaje.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 57 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Itamaraty''s Foreign Service internal affairs office (Corregedoria do Serviço Exterior) closed in 1996 the disciplinary administrative proceedings COR 01/96 opened against him, accepting the report of the inquiry committee; this is an administrative, not a judicial, decision and is not equivalent to an acquittal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 58 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La Corregedoria do Serviço Exterior (órgano de asuntos internos) del Itamaraty archivó en 1996 el expediente administrativo disciplinario COR 01/96 abierto contra él, acogiendo el informe de la comisión de investigación; se trata de una decisión administrativa, no judicial, que no equivale a una absolución.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 58 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPI found banking activity more than 50% above his declared income in 1995 and 1996 and sent the report to the Federal Prosecution Service (MPF); the ambassador attributed the difference to the sale of a property for R$ 300,000.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 59 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La CPI detectó un movimiento bancario más de un 50 % superior a los ingresos declarados en 1995 y 1996 y remitió el informe al MPF; el embajador atribuyó la diferencia a la venta de un inmueble por 300.000 reales.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 59 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Minister of the Air Force in 1995, he left office after it emerged that he had stayed three days at Assumpção''s home; to the CPI, he admitted the stay, denied wrongdoing and said that Raytheon had already been chosen before his term.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 60 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ministro de la Aeronáutica en 1995, dejó el cargo tras conocerse que se había alojado tres días en casa de Assumpção; ante la CPI admitió el alojamiento, negó culpa y dijo que Raytheon ya había sido elegida antes de su gestión.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 60 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He obtained authorisation from the 2nd Narcotics Court of the Federal District to tap the ambassador by citing anonymous tips about drug trafficking; the Senate committee saw strong signs that the tap was aimed at the ambassador, and internal inquiries found signs of disciplinary breaches. The police chief maintained that he followed usual procedure.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 61 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Obtuvo del Juzgado 2.º de Estupefacientes del Distrito Federal la autorización para intervenir el teléfono del embajador alegando denuncias anónimas de narcotráfico; la comisión del Senado vio fuertes indicios de que la escucha iba dirigida al embajador, y las investigaciones internas apuntaron indicios de infracciones disciplinarias. El comisario sostuvo que siguió el procedimiento habitual.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 61 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He took a copy of the wiretap tape to Francisco Graziano outside the Federal Police''s chain of command, and an internal inquiry found signs of a disciplinary breach; he said he acted in order to inform the president.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 62 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Llevó una copia de la cinta de la escucha a Francisco Graziano al margen de los cauces jerárquicos de la Policía Federal, y una investigación interna apuntó indicios de infracción disciplinaria; afirmó haber actuado para informar al presidente.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 62 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
