INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'As president, he removed ESCA after a meeting of the National Defence Council on 27 May 1995 and dismissed the ambassador after the scandal; in a letter, he stated that Júlio César never pressed for anything regarding the Sivam.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 69 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
