INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the Federal Regional Court of the 3rd Region (TRF-3) in 2006 of money laundering, corruption and bid fraud; the Federal Prosecution Service (MPF) pointed to assets out of proportion to his income, including Swiss deposits confiscated by the courts. The defence maintained he took no part in any diversion of funds.', NULL, 'Amount in US dollars, with no conversion in the source; assets confiscated', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 84 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
