INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the TRF-3 in 2006 of embezzlement (peculato), fraud (estelionato) and active corruption in the diversion of funds from the building works; the Supreme Federal Court (STF) upheld the sentence of 31 years and 6 months in 2015, reduced to about 26 years because two offences were time-barred. The defence argued insufficient evidence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 88 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
