INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El último acusado del proceso sobre la cuenta CC5 del banco paraguayo, un exdirector residente en el extranjero, fue absuelto por la Justicia Federal en diciembre de 2009, con lo que concluyó la causa penal principal sobre esa cuenta.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 219 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
