INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPMI report attributed to him the movement of about R$ 8 billion of the amount analysed and recommended that he be formally named a suspect; he was never prosecuted for these facts.', NULL, 'Movement attributed by the CPMI report, not an amount of diversion established in court', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 224 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El informe de la CPMI le atribuyó el movimiento de unos 8.000 millones de reales del montante analizado y recomendó su imputación; nunca llegó a ser procesado por estos hechos.', NULL, 'Movimiento atribuido por el informe de la CPMI, no un importe de desvío determinado judicialmente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 224 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In August 1998 he obtained a fraudulent loan of US$ 1.5 million for Jabur Toyopar from the bank''s Grand Cayman branch, in return for a bribe of US$ 131,000 to the then Director of International Operations.', NULL, 'Amount of the loan obtained; the bribe established was US$ 131,000. Amounts in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 225 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En agosto de 1998 obtuvo un préstamo fraudulento de 1,5 millones de dólares para Jabur Toyopar en la sucursal de Gran Caimán del banco, mediante un soborno de 131.000 dólares al entonces director de Operaciones Internacionales.', NULL, 'Importe del préstamo obtenido; el soborno determinado fue de 131.000 dólares. Importes en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 225 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Sentenced in September 2014 to 4 years and 4 months for active corruption in a case brought in 2003 and resumed after his plea agreement was breached; in the same judgment he was acquitted of the charge of fraudulent management and the defence said it would appeal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 226 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en septiembre de 2014 a 4 años y 4 meses por cohecho activo en una causa iniciada en 2003 y retomada tras la ruptura de su acuerdo de colaboración; en la misma sentencia fue absuelto de la imputación de gestión fraudulenta y la defensa informó de que recurriría.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 226 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
