INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The CPMI rapporteur said he had received documents from the US prosecutors proving a joint account opened in New York in 1994, when he was Finance Secretary, and closed in 1997; Pitta denied the existence of the account to the press.', NULL, 'Opening amount of the account according to a statement taken by the CPMI; amount in US dollars, with no conversion in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 232 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El relator de la CPMI afirmó haber recibido documentos del Ministerio Público estadounidense que acreditaban una cuenta conjunta abierta en Nueva York en 1994, cuando era secretario de Hacienda, y cerrada en 1997; Pitta negaba a la prensa la existencia de la cuenta.', NULL, 'Importe de apertura de la cuenta según una declaración recogida por la CPMI; importe en dólares, sin conversión en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 232 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
