INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged on 25 September 2006 with criminal conspiracy (formação de quadrilha) and passive corruption, accused of knowing about the scheme and backing the officials involved; the defence denies it, recalling that the initial complaint to the MPF came from him, and the Federal Regional Court of the 5th Region (TRF-5) acquitted him unanimously on 24 March 2010 for lack of evidence, after the MPF itself asked for his acquittal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 257 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
