INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in 2006; according to the report published by Folha, his group would have collected about R$ 15 million, and according to the lobbyist Francisco Honorato, the lobbyist Laerte Correa had his authorisation to raise money for the PT. Delúbio told the Federal Police that he was introduced to Laerte but never authorised him to speak on his behalf and denied having set up a fundraising strategy at the ministry.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 259 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en 2006; según el informe publicado por Folha, su grupo habría alcanzado unos 15 millones de reales, y según el lobista Francisco Honorato, el lobista Laerte Correa tenía su autorización para recaudar para el PT. Delúbio dijo a la Policía Federal que le presentaron a Laerte pero que nunca lo autorizó a hablar en su nombre y negó haber montado una estrategia de recaudación en el ministerio.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 259 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged on 25 September 2006 with passive corruption, money laundering and criminal conspiracy, with the indictment accepted on 28 October; the Federal Prosecution Service (MPF) said he was the recipient of part of the bribe, with more than R$ 1 million received according to the intercepts, including an intercepted consignment of R$ 723,000. The defence denies having authorised fundraising at the ministry.', NULL, 'Cash consignment intercepted and destined for Delúbio according to the MPF; the prosecutor spoke of more than R$ 1 million received and the Federal Police, according to Folha, attributed about R$ 15 million to his group; no amount proven in any judgment found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 260 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado el 25 de septiembre de 2006 de cohecho pasivo, blanqueo de capitales y asociación ilícita, con acusación admitida el 28 de octubre; el MPF afirmó que era destinatario de parte del soborno, con más de 1 millón de reales recibidos según las interceptaciones, incluido un envío de 723.000 reales interceptado. La defensa niega haber autorizado recaudación en el ministerio.', NULL, 'Envío en efectivo interceptado y destinado a Delúbio según el MPF; el fiscal habló de más de 1 millón de reales recibidos y la Policía Federal, según Folha, atribuyó unos 15 millones de reales a su grupo; ningún importe acreditado en sentencia localizada', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 260 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
