INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Coordinador general de Recursos Logísticos, que empezó a trabajar en el órgano por invitación del ministro Humberto Costa; detenido en la operación en mayo de 2004, el ministerio ordenó su cese inmediato.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 261 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Arrested in May 2004 and formally named a suspect in the first inquiry, he was charged in 2006 as a person trusted by the minister and responsible for the strategic management of the tenders, acting, according to the MPF, with Humberto Costa''s knowledge; his defence was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 262 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Detenido en mayo de 2004 e imputado en la primera investigación, fue acusado en 2006 como persona de confianza del ministro y responsable de la gestión estratégica de las licitaciones, actuando, según el MPF, con conocimiento de Humberto Costa; no se localizó su defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 262 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former ministry employee during the Fernando Henrique Cardoso government, dismissed in 2003, at the start of the Lula government.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 263 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exfuncionario del ministerio durante el Gobierno de Fernando Henrique Cardoso, cesado en 2003, al inicio del Gobierno de Lula.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 263 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged in 2006 as the scheme''s lobbyist in the executive branch under the PSDB administration, with a role similar to Luiz Cláudio''s according to the MPF; the prosecutor said there was no evidence linking former minister José Serra to the fraud, and Platão''s defence was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 264 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado en 2006 como lobista de la trama en el Ejecutivo durante la gestión del PSDB, con una actuación similar a la de Luiz Cláudio según el MPF; el fiscal dijo que no había indicios que vincularan al exministro José Serra con el fraude, y no se localizó la defensa de Platão.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 264 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Businessman arrested in May 2004 and formally named a suspect in the first inquiry, identified by the Federal Police as one of those who allegedly paid bribes to officials; the MPF named him in 2006 among those investigated for activity dating from the PSDB era, and his defence was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 265 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Empresario detenido en mayo de 2004 e imputado en la primera investigación, señalado por la Policía Federal como uno de los que habrían pagado sobornos a funcionarios; el MPF lo citó en 2006 entre los investigados por actuaciones ya en la etapa del PSDB, y no se localizó su defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 265 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Businessman arrested in May 2004 and formally named a suspect in the first inquiry, identified by the Federal Police as one of those who allegedly paid bribes to officials; the MPF named him in 2006 among those investigated for activity under the previous administration, and his defence was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 266 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Empresario detenido en mayo de 2004 e imputado en la primera investigación, señalado por la Policía Federal como uno de los que habrían pagado sobornos a funcionarios; el MPF lo citó en 2006 entre los investigados por actuaciones en la gestión anterior, y no se localizó su defensa.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 266 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Lobbyist arrested and formally named a suspect in 2004; according to the MPF, intercepts caught him saying he had received R$ 15 million from the scheme, and his defence was not found.', NULL, 'Amount stated by Laerte in telephone intercepts, according to the MPF; the Federal Police, according to Folha, attributed about R$ 15 million to Delúbio''s group; not confirmed in any judgment found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 267 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Lobista detenido e imputado en 2004; según el MPF, las interceptaciones lo sorprendieron afirmando haber recibido 15 millones de reales de la trama, y no se localizó su defensa.', NULL, 'Importe dicho por Laerte en interceptaciones telefónicas, según el MPF; la Policía Federal, según Folha, atribuyó unos 15 millones de reales al grupo de Delúbio; no confirmado en sentencia localizada', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 267 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the testimony of the lobbyist Francisco Honorato to the Federal Police, Laerte had Delúbio''s authorisation to raise funds for the PT in the 2002 campaign; Delúbio says he was introduced to Laerte but never authorised him to speak on his behalf, and Humberto Costa said he knew nothing of this activity.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 268 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la declaración del lobista Francisco Honorato a la Policía Federal, Laerte tenía autorización de Delúbio para recaudar fondos para el PT en la campaña de 2002; Delúbio dice que le presentaron a Laerte pero que nunca lo autorizó a hablar en su nombre, y Humberto Costa dijo desconocer esa actuación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 268 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Arrested in February 2007 on accusations of laundering money from frauds against the Ministry of Health; according to the report, he represented foreign laboratories and bribed officials to win tenders, and the Federal Court in São Paulo froze R$ 8.6 million in a UBS account in the name of his brother and mother. The defence is not given in this source; in a later administrative misconduct case, he disputes the transcripts of the intercepts.', NULL, 'Amount frozen by the courts in a relative''s account, not a proven bribe amount; the source cites a shortfall of R$ 120 million between 1997 and 2004 without saying who established it', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 269 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Detenido en febrero de 2007 acusado de blanquear dinero de fraudes contra el Ministerio de Sanidad; según el reportaje, representaba a laboratorios extranjeros y sobornaba a funcionarios para ganar concursos, y la Justicia Federal de São Paulo bloqueó 8,6 millones de reales en una cuenta de UBS a nombre de su hermano y de su madre. La defensa no consta en esta fuente; en una acción posterior por improbidad, impugna las transcripciones de las interceptaciones.', NULL, 'Importe bloqueado judicialmente en una cuenta de familiares, no importe acreditado de soborno; la fuente cita un agujero de 120 millones de reales entre 1997 y 2004 sin indicar quién lo determinó', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 269 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In 2020, the Federal Regional Court of the 1st Region (TRF-1) decided that it was not possible to punish him for criminal association and bid fraud in the criminal case under Operation Vampiro, which continues against other defendants under seal; the source does not detail the grounds of the decision.', NULL, 'The source speaks only of the impossibility of punishing him, without detailing the grounds; it is not treated here as an acquittal on the merits', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 270 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En 2020, el TRF-1 decidió la imposibilidad de castigarlo por asociación criminal y fraude en licitación en la causa penal de la Operación Vampiro, que sigue contra otros acusados bajo secreto de sumario; la fuente no detalla el fundamento de la decisión.', NULL, 'La fuente habla solo de imposibilidad de castigarlo, sin detallar el fundamento; no se trata aquí como absolución sobre el fondo', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 270 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Defendant in an administrative misconduct case before the TRF-1, in which the MPF alleges an agreement to divide up the blood-product market in international tenders and the payment of bribes to the tender committee, and seeks repayment of R$ 27.5 million; he asks for the case to be dismissed, claiming the Federal Police mistranscribed the intercepts.', NULL, 'Repayment to the public purse sought by the MPF, to be paid jointly by all defendants; not an amount ordered', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 271 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado en una acción por improbidad administrativa en el TRF-1, en la que el MPF señala un acuerdo de reparto del mercado de hemoderivados en licitaciones internacionales y el pago de sobornos a la comisión de licitación, y reclama un resarcimiento de 27,5 millones de reales; él pide que se desestime, alegando transcripciones equivocadas de las interceptaciones por la Policía Federal.', NULL, 'Resarcimiento al erario reclamado por el MPF, a pagar solidariamente por todos los acusados; no es un importe condenado', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 271 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Body harmed by the fraud in supply tenders; the MPF prosecutor Marlon Weichert estimated in December 2004 a loss of US$ 100 million in blood products, while the ministry''s own estimate of R$ 2 billion over 13 years was not confirmed by the Federal Police in the first inquiry.', NULL, 'Estimate by the prosecutor Marlon Weichert, with a conversion of about R$ 280 million given by the source; the ministry estimated R$ 2 billion over 13 years, not confirmed by the Federal Police in June 2004', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 272 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Órgano perjudicado por los fraudes en licitaciones de suministros; el fiscal del MPF Marlon Weichert estimó en diciembre de 2004 una pérdida de 100 millones de dólares en hemoderivados, mientras que la estimación del propio ministerio, de 2.000 millones de reales en 13 años, no fue confirmada por la Policía Federal en la primera investigación.', NULL, 'Estimación del fiscal Marlon Weichert, con una conversión de unos 280 millones de reales dada por la fuente; el ministerio estimó 2.000 millones de reales en 13 años, no confirmados por la Policía Federal en junio de 2004', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 272 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He chaired the state lottery in the Benedita da Silva government when he was recorded, in 2002, soliciting a bribe from Carlinhos Cachoeira.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 273 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidía la lotería estatal en el Gobierno de Benedita da Silva cuando fue grabado, en 2002, solicitando un soborno a Carlinhos Cachoeira.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 273 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the February 2002 recording, he asked Cachoeira for 1% of the contract between the Combralog Consortium and Loterj and for help with election campaigns; he was convicted in 2012, at first instance, of passive corruption and an offence under the Public Procurement Law (12 years'' imprisonment and 3 years'' detention). The defence argued impossible crime, a thesis rejected in the judgment.', NULL, 'Corresponds to 1% of the contract, according to the Rio de Janeiro State Prosecution Service (MP-RJ) indictment; amount requested, with no record of payment in the source', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 274 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la grabación de febrero de 2002, solicitó a Cachoeira el 1 % del contrato entre el Consorcio Combralog y la Loterj y ayuda para campañas electorales; fue condenado en 2012, en primera instancia, por cohecho pasivo y delito de la Ley de Licitaciones (12 años de reclusión y 3 de detención). La defensa sostuvo la tesis del delito imposible, rechazada en la sentencia.', NULL, 'Corresponde al 1 % del contrato, según la acusación del MP-RJ; importe solicitado, sin constancia de pago en la fuente', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 274 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted of administrative misconduct (improbidade) for his role in the 2003 meetings with Gtech; in 2011 the TRF-1 raised the fine to 15 times his salary and imposed suspension of political rights and a ban on contracting for five years. Waldomiro claimed he went to the meetings under blackmail and appealed to the STJ.', NULL, 'Amount claimed by the AGU in 2013, with adjustments and fees, according to Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 275 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por improbidad administrativa por su actuación en 2003 en las reuniones con Gtech; en 2011 el TRF-1 elevó la multa a 15 veces su remuneración e impuso suspensión de derechos políticos y prohibición de contratar durante cinco años. Waldomiro alegó haber ido a las reuniones bajo chantaje y recurrió al STJ.', NULL, 'Importe reclamado por la AGU en 2013, con actualización y honorarios, según Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 275 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He testified to the Bingos CPI in August 2005, protected by an STF habeas corpus: he denied having extorted Cachoeira, said he went to the meeting to defend Armando Dile''s interests and admitted passing R$ 100,000 from Cachoeira to the campaign of Geraldo Magela, the PT candidate for governor of the Federal District.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 276 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Declaró ante la CPI de los Bingos en agosto de 2005, amparado por un habeas corpus del STF: negó haber extorsionado a Cachoeira, dijo que fue a la reunión para defender los intereses de Armando Dile y admitió haber transferido 100.000 reales de Cachoeira a la campaña de Geraldo Magela, candidato del PT al Gobierno del Distrito Federal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 276 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Defendant since January 2011 in a criminal case before the 10th Federal Court in Brasília for extortion by a public official (concussão), fraud (estelionato) and active and passive corruption over the renewal of the Caixa–Gtech contract; according to the indictment, he made the renewal conditional on the hiring of Buratti for more than R$ 10 million. Waldomiro has always denied the accusations.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 277 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado desde enero de 2011 en una causa penal del Juzgado Federal 10.º de Brasilia por concusión, estafa y cohecho activo y pasivo en la renovación del contrato Caixa–Gtech; según la acusación, habría condicionado la renovación a la contratación de Buratti por más de 10 millones de reales. Waldomiro siempre negó las acusaciones.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 277 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In April 2013, the Rio de Janeiro State Court of Justice (TJ-RJ) reduced to 6 years and 8 months'' imprisonment the sentence in the Loterj conviction and acquitted him of the offence of tender fraud.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 278 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En abril de 2013, el Tribunal de Justicia de Río de Janeiro (TJ-RJ) redujo a 6 años y 8 meses de reclusión la pena de la condena de la Loterj y lo absolvió del delito de fraude en la licitación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 278 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 4 May 2018, the STJ refused the request for provisional enforcement of Waldomiro''s sentence because an appeal was pending; the later outcome was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 279 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 4 de mayo de 2018, el STJ denegó la solicitud de ejecución provisional de la pena de Waldomiro por haber un recurso pendiente; no se localizó el desenlace posterior.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 279 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Representative of the Combralog Consortium, he recorded the February 2002 conversation in which he promised an advantage to Waldomiro; he was convicted in 2012, at first instance, of active corruption and an offence under the Public Procurement Law (8 years'' imprisonment). The defence argued that the clandestine recording was unlawful evidence, a thesis rejected by the judge.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 280 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Representante del Consorcio Combralog, grabó la conversación de febrero de 2002 en la que prometió una ventaja a Waldomiro; fue condenado en 2012, en primera instancia, por cohecho activo y delito de la Ley de Licitaciones (8 años de reclusión). La defensa alegó que la grabación clandestina era prueba ilícita, tesis rechazada por la jueza.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 280 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In April 2013, the TJ-RJ reduced the sentence to 6 years and 8 months'' imprisonment and acquitted him of tender fraud; the rapporteur considered that Cachoeira recorded the conversation because he felt Waldomiro was demanding too much.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 281 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En abril de 2013, el TJ-RJ redujo la pena a 6 años y 8 meses de reclusión y lo absolvió del fraude en la licitación; el ponente consideró que Cachoeira grabó la conversación por entender que Waldomiro exigía demasiado.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 281 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 4 May 2018, Justice Nefi Cordeiro (STJ), at the request of the MPF, ordered the immediate enforcement of the 6-year, 8-month sentence, following the STF''s position on enforcement after the second instance, although appeals were still pending.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 282 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 4 de mayo de 2018, el ministro Nefi Cordeiro (STJ), a petición del MPF, ordenó la ejecución inmediata de la pena de 6 años y 8 meses, siguiendo el criterio del STF sobre ejecución tras la segunda instancia, aunque aún había recursos pendientes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 282 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Representative of the consortium, which signed contract 3/2002 with Loterj, under which the recorded negotiation took place.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 283 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Representante del consorcio, que firmó el contrato 3/2002 con la Loterj, en cuyo marco se produjo la negociación grabada.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 283 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He took part in the meetings with Gtech executives in 2003 and is a defendant in the criminal case before the 10th Federal Court; according to the MPF, the planned bribe payments did not take place. G1 noted that it was awaiting a response from Cachoeira''s defence, whose position was not found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 284 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Participó en las reuniones con directivos de Gtech en 2003 y es acusado en la causa penal del Juzgado Federal 10.º; según el MPF, los pagos de soborno previstos no se produjeron. G1 registró que esperaba respuesta de la defensa de Cachoeira, cuya postura no se localizó.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 284 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Acquitted at first instance, he was convicted by the TRF-1 in 2011 of administrative misconduct (improbidade), with a fine of five times Waldomiro''s salary, suspension of political rights and a ban on contracting for five years, for the attempt to have himself imposed as a Gtech consultant. Buratti denied having been an intermediary and is appealing to the STJ.', NULL, 'Amount claimed by the AGU in 2013, with additions, according to Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 285 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Absuelto en primera instancia, fue condenado por el TRF-1 en 2011 por improbidad, con multa de cinco veces la remuneración de Waldomiro, suspensión de derechos políticos y prohibición de contratar durante cinco años, por el intento de imponerse como consultor de Gtech. Buratti negó haber sido intermediario y recurre al STJ.', NULL, 'Importe reclamado por la AGU en 2013, con recargos, según Congresso em Foco', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 285 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to Gtech executives cited in the TRF-1 ruling, in early April 2003 he demanded between R$ 15 million and R$ 20 million, later reduced to R$ 6 million, so as not to block the signing of the contract; Buratti denies having acted as an intermediary.', NULL, 'Last amount demanded according to Gtech executives; the TRF-1 cites at least R$ 10 million and the CPI cited R$ 16 million; no proof of payment', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 286 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según directivos de Gtech citados en la sentencia del TRF-1, exigió a principios de abril de 2003 entre 15 y 20 millones de reales, reducidos después a 6 millones, para no impedir la firma del contrato; Buratti niega haber actuado como intermediario.', NULL, 'Último importe exigido según directivos de Gtech; el TRF-1 cita al menos 10 millones de reales y la CPI citó 16 millones; sin prueba de pago', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 286 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Operator of Caixa''s lottery system, its contract was renewed in April 2003 after meetings with Waldomiro and Cachoeira. Its executives say they were victims of extortion and deny payment, while an MPF opinion cited by the TRF-1 invokes a Bingos CPI report according to which the company negotiated and paid part of the bribe.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 287 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Operadora del sistema de loterías de la Caixa, su contrato fue renovado en abril de 2003 tras reuniones con Waldomiro y Cachoeira. Sus directivos afirman haber sido víctimas de extorsión y niegan el pago, mientras que un dictamen del MPF citado en el TRF-1 invoca un informe de la CPI de los Bingos según el cual la empresa negoció y pagó parte del soborno.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 287 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It provided the lottery processing service to Caixa; the 2000 contract expired in January 2003, was extended for 90 days and renewed in April 2003.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 288 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Prestaba a la Caixa el servicio de procesamiento de las loterías; el contrato de 2000 venció en enero de 2003, se prorrogó por 90 días y se renovó en abril de 2003.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 288 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Client for the lottery service renewed in 2003; the Federal Court of Accounts (TCU) found a loss of R$ 433 million to Caixa under the contract with Gtech, an amount the AGU says is unrelated to the fine in the administrative misconduct case.', NULL, 'TCU figure cited by Congresso em Foco; the TRF-1 recorded that damage to the public purse had not been demonstrated in the administrative misconduct case', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 289 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Contratante del servicio de loterías renovado en 2003; el TCU señaló un perjuicio de 433 millones de reales a la Caixa en el contrato con Gtech, importe que la AGU dice que no guarda relación con la multa de la acción por improbidad.', NULL, 'Cifra del TCU citada por Congresso em Foco; el TRF-1 registró que no quedó demostrado un daño al erario en la acción por improbidad', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 289 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the video released by Época, Waldomiro asked Cachoeira for money for PT candidates'' campaigns, as well as a bribe for himself; he said he passed R$ 100,000 to the committee of Geraldo Magela, the PT candidate for governor of the Federal District. The party is not named as a subject of investigation or a defendant in the sources consulted.', NULL, 'Amount stated by Waldomiro himself to Época and to the Bingos CPI', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 290 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En el vídeo divulgado por Época, Waldomiro pedía a Cachoeira dinero para campañas de candidatos del PT, además de un soborno para sí; afirmó haber transferido 100.000 reales al comité de Geraldo Magela, candidato del PT al Gobierno del Distrito Federal. El partido no figura como investigado ni como acusado en las fuentes consultadas.', NULL, 'Importe declarado por el propio Waldomiro a Época y a la CPI de los Bingos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 290 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'State body whose tender (Notice 1/2002) and contract with Combralog were the subject of the corruption investigated; the release of the recording led to the Loterj CPI, and the TJ-RJ acquitted the defendants of the offence of tender fraud in 2013.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 291 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Organismo estatal cuya licitación (pliego 1/2002) y contrato con Combralog fueron objeto de la corrupción investigada; la divulgación de la grabación dio lugar a la CPI de la Loterj, y el TJ-RJ absolvió en 2013 a los acusados del delito de fraude en la licitación.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 291 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Consortium that signed the contract with Loterj whose tender notice was the target of the accusation; the indictment alleged that the change to the notice would favour the company Hebara, and the TJ-RJ acquitted the defendants of tender fraud in 2013.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 292 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Consorcio firmante del contrato con la Loterj cuyo pliego fue objeto de la acusación; la acusación señaló que la modificación del pliego favorecería a la empresa Hebara, y el TJ-RJ absolvió a los acusados del fraude en la licitación en 2013.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 292 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A member of the PT, he chaired the party''s state branch in Ceará for eight years and was a state deputy at the time of the arrest in the act.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 293 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Afiliado al PT, presidió la dirección estatal del partido en Ceará durante ocho años y era diputado estatal en la época de la detención en flagrante.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 293 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was charged by the Federal Prosecution Service (MPF), in December 2005, in the administrative misconduct case as an alleged beneficiary of the BNB contract with the STN consortium, for having recommended Kennedy Moura to the bank. He called the suspicion absurd and said the charge was meant to damage the PT.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 294 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fue acusado por el MPF, en diciembre de 2005, en la acción por improbidad como supuesto beneficiario del contrato del BNB con el consorcio STN, por haber recomendado a Kennedy Moura al banco. Calificó la sospecha de absurda y dijo que la acusación pretende perjudicar al PT.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 294 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'On 21 June 2012, the 1st Panel of the STJ unanimously decided that he should cease to be a defendant in the administrative misconduct case, holding that a relationship of friendship and political companionship does not support the action; the MPF said it intended to appeal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 295 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El 21 de junio de 2012, la Primera Sala del STJ decidió por unanimidad que dejara de ser acusado en la acción por improbidad, al entender que una relación de amistad y compañerismo político no sustenta la acción; el MPF dijo que pretendía recurrir.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 295 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in Ceará recognised that the offence was time-barred and extinguished his liability on 19 August 2021, without ruling on the merits. The defence says the State did not prove any involvement on his part.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 296 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal de Ceará reconoció la prescripción y extinguió su responsabilidad penal el 19 de agosto de 2021, sin juicio sobre el fondo. La defensa afirma que el Estado no acreditó ninguna participación suya.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 296 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The arrest in the act involved the then PT Organisation Secretary in Ceará and led the Federal Police to investigate possible undeclared funds (caixa dois) in the state branch, a hypothesis the Federal Court recorded in 2019 as unproven.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 297 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La detención en flagrante afectó al entonces secretario de Organización del PT de Ceará y llevó a la Policía Federal a investigar una posible caja B (caixa dois) en la dirección estatal, hipótesis que la Justicia Federal registró en 2019 como no acreditada.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 297 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was arrested in the act at Congonhas airport on 8 July 2005, boarding a flight to Fortaleza, with R$ 209,000 in a briefcase and US$ 100,559 strapped to his body, with no proof of origin; the MPF maintains that it was part of a bribe paid by the STN consortium for the BNB financing. The defence claimed the money came from an unidentified friend to open two businesses and has nothing to do with the financing.', 'R$ 209,000 and US$ 100,559', 'Sum of R$ 209,000 in cash and US$ 100,559 converted at the PTAX closing rate of 8/7/2005 (R$ 2.3675), equivalent to R$ 238,073, total R$ 447,073; Congresso em Foco converted US$ 100,000 into about R$ 252,000 and the 2019 decision cites about R$ 600,000 in adjusted values', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 298 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Fue detenido en flagrante en Congonhas el 8 de julio de 2005, al embarcar hacia Fortaleza, con 209.000 reales en un maletín y 100.559 dólares pegados al cuerpo, sin acreditar su origen; el MPF sostiene que formaban parte de un soborno pagado por el consorcio STN por la financiación del BNB. La defensa alegó que el dinero venía de un amigo no identificado para abrir dos negocios y que no tiene nada que ver con la financiación.', 'R$ 209.000 y US$ 100.559', 'Suma de 209.000 reales en efectivo y 100.559 dólares convertidos a la cotización PTAX de cierre del 8/7/2005 (2,3675 reales), equivalentes a 238.073 reales, total de 447.073 reales; Congresso em Foco convirtió 100.000 dólares en unos 252.000 reales y la decisión de 2019 cita unos 600.000 reales en valores corregidos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 298 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the administrative misconduct case, the 2012 judgment did not accept that the money was an advantage linked to the financing; according to Aos Fatos, the TRF-5 ordered him to pay a fine in 2014, and O Povo lists him among the three ordered to pay a fine. The amount, grounds and any appeal were not found.', NULL, 'Amount of the fine not found in the sources read', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 299 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la acción por improbidad, la sentencia de 2012 no reconoció que el dinero fuera una ventaja vinculada a la financiación; según Aos Fatos, el TRF-5 lo condenó a pagar una multa en 2014, y O Povo lo incluye entre los tres condenados a multa. No se localizaron el importe, el fundamento ni un eventual recurso.', NULL, 'Importe de la multa no localizado en las fuentes leídas', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 299 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in 2019 rejected the closure requested by the MPF, which cited time-barring of reckless management and influence peddling; on 19 August 2021 it recognised the time-bar and declared extinguished the liability of him and three others involved, without ruling on the merits.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 300 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal rechazó en 2019 el archivo solicitado por el MPF, que alegaba prescripción de gestión temeraria y tráfico de influencias; el 19 de agosto de 2021 reconoció la prescripción y declaró extinguida la responsabilidad penal de él y de otros tres implicados, sin juicio sobre el fondo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 300 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He was parliamentary aide to the then state deputy José Guimarães, who says he dismissed the aide after the arrest in the act and felt betrayed in the trust he had placed in him.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 301 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Era asesor parlamentario del entonces diputado estatal José Guimarães, quien afirma haberlo cesado tras la detención en flagrante y haber sido traicionado en la confianza que depositaba en él.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 301 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He held the post of special adviser to the BNB presidency, to which, according to the MPF, he was appointed through José Guimarães''s influence and from which he allegedly arranged the financing for the STN. In his defence, he said he merely performed institutional liaison and customer-service functions.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 302 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ocupaba el cargo de asesor especial de la presidencia del BNB, adonde, según el MPF, fue designado por influencia de José Guimarães y desde donde habría articulado la financiación al STN. En su defensa, dijo que solo ejercía funciones institucionales de enlace y atención a clientes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 302 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The MPF pointed to evidence that the money seized was a bribe for influence peddling in the STN contract, which he allegedly facilitated; the BNB''s internal inquiry (October 2005) concluded that he took part in meetings with consortium executives but found no proof of any improper personal advantage.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 303 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El MPF señaló indicios de que el dinero incautado era un soborno por tráfico de influencias en el contrato con el STN, que él habría facilitado; la investigación interna del BNB (octubre de 2005) concluyó que participó en reuniones con directivos del consorcio, pero no obtuvo pruebas de ventaja personal indebida.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 303 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to O Povo, he was one of the three ordered to pay a fine in the administrative misconduct case, alongside Adalberto and Roberto Smith; the 2012 judgment had cleared him for lack of evidence. Aos Fatos places the fine at the TRF-5 in 2014; the amount and grounds were not found.', NULL, 'Amount of the fine not found in the sources read; year 2014 according to Aos Fatos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 304 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según O Povo, fue uno de los tres condenados a multa en la acción por improbidad, junto con Adalberto y Roberto Smith; la sentencia de 2012 había descartado su responsabilidad por falta de pruebas. Aos Fatos sitúa la condena a multa en el TRF-5 en 2014; no se localizaron el importe ni el fundamento.', NULL, 'Importe de la multa no localizado en las fuentes leídas; año 2014 según Aos Fatos', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 304 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In the criminal inquiry, the Federal Court in Ceará declared his liability extinguished on 19 August 2021, as time-barred and without ruling on the merits, together with other suspects.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 305 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En la investigación penal, la Justicia Federal de Ceará declaró extinguida su responsabilidad penal el 19 de agosto de 2021, por prescripción y sin juicio sobre el fondo, junto con otros investigados.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 305 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He chaired the BNB when the Board approved, in June 2004, the financing to the STN; the MPF described him as negligent and complicit in the irregularities attributed to Kennedy Moura. He and the other executives maintain that the operation was lawful, which the TCU confirmed in December 2005.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 306 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidía el BNB cuando el Directorio aprobó, en junio de 2004, la financiación al STN; el MPF lo señaló como omiso y connivente con las irregularidades atribuidas a Kennedy Moura. Él y los demás directivos sostienen que la operación fue regular, lo que el TCU acreditó en diciembre de 2005.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 306 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Ordered at first instance, on 14 December 2012, to pay a civil fine of R$ 10,000 for breaching the principle of impersonality by approving the rule changes that made the STN financing possible, with the judgment not finding that a bribe was paid. The defence maintained that the operation was lawful, as confirmed by the TCU.', NULL, 'Civil fine set in the judgment of 14/12/2012; final amount and outcome of appeals not found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 307 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en primera instancia, el 14 de diciembre de 2012, a una multa civil de 10.000 reales por vulnerar el principio de impersonalidad al aprobar los cambios de reglas que hicieron viable la financiación al STN, sin que la sentencia reconociera pago de soborno. La defensa sostuvo la regularidad de la operación, acreditada por el TCU.', NULL, 'Multa civil fijada en la sentencia del 14/12/2012; importe final y resultado de los recursos no localizados', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 307 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It granted the STN consortium, using FNE funds and after changing internal rules to fit the operation, financing approved on 25 June 2004; the MPF maintains that the bribe came from it, the TCU found it lawful and the 2012 judgment found a breach of impersonality but no proof of an improper advantage.', NULL, 'Amount of the financing to the STN according to the MPF petition (R$ 299,995,032.33), which the press rounds to R$ 300 million; it is not the amount of the alleged bribe', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 308 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Concedió al consorcio STN, con fondos del FNE y tras modificar normas internas para encuadrar la operación, una financiación aprobada el 25 de junio de 2004; el MPF sostiene que de ella salió el soborno, el TCU concluyó que fue regular y la sentencia de 2012 reconoció una vulneración de la impersonalidad, pero no prueba de ventaja indebida.', NULL, 'Importe de la financiación al STN según la petición del MPF (299.995.032,33 reales), que la prensa redondea a 300 millones de reales; no es el importe del supuesto soborno', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 308 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Consortium that borrowed the BNB financing, identified by the MPF as the payer of the bribe; the 2012 judgment ordered it to pay a civil fine for having benefited from the acts that breached impersonality, without finding that an improper advantage was paid. The consortium disputes this and cites the lawfulness confirmed by the TCU.', NULL, 'Civil fine set in the judgment of 14/12/2012; later press reports on those convicted in the case do not list it and the outcome of the appeal was not found', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 309 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Consorcio prestatario de la financiación del BNB, señalado por el MPF como pagador del soborno; la sentencia de 2012 lo condenó a una multa civil por haberse beneficiado de los actos que vulneraron la impersonalidad, sin reconocer pago de ventaja indebida. El consorcio lo impugna e invoca la regularidad acreditada por el TCU.', NULL, 'Multa civil fijada en la sentencia del 14/12/2012; los reportajes posteriores sobre condenados en el caso no lo mencionan y no se localizó el resultado del recurso', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 309 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It holds the majority of the share capital of the STN consortium, the borrower of the BNB financing.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 310 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Posee la mayoría del capital social del consorcio STN, prestatario de la financiación del BNB.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 310 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The MPF named it as a member of the consortium that allegedly paid the bribe, and one of its directors allegedly handed the money to Adalberto; the 2012 judgment did not hold it responsible for lack of proof of its own act or of a benefit, and the company denies any wrongdoing.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 311 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El MPF la señaló como integrante del consorcio que habría pagado el soborno, y uno de sus directivos habría entregado el dinero a Adalberto; la sentencia de 2012 no la responsabilizó por falta de prueba de acto propio o de beneficio, y la empresa niega cualquier ilícito.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 311 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Hired by the STN to draw up the financing project, it allegedly received about R$ 1.97 million against R$ 20,000 provided for in the project, which the MPF saw as a possible vehicle for improper advantages. The company says it was a regular advisory contract; the 2012 judgment dismissed the claim against it and the MPF itself asked for its acquittal.', NULL, 'Amount identified by the BNB''s internal inquiry according to the MPF petition; the company reports R$ 1,970,817.36 received under a technical advisory contract', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 312 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Contratada por el STN para elaborar el proyecto de financiación, habría recibido unos 1,97 millones de reales frente a los 20.000 previstos en el proyecto, lo que el MPF vio como posible vehículo de ventajas indebidas. La empresa dice que fue un contrato regular de asesoría; la sentencia de 2012 rechazó la demanda contra ella y el propio MPF pidió su absolución.', NULL, 'Importe señalado por la investigación interna del BNB según la petición del MPF; la empresa informa de 1.970.817,36 reales recibidos por un contrato de asesoría técnica', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 312 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A member of the PT, federal deputy for São Paulo and Chief of Staff (Casa Civil) until he resigned on 16 June 2005, when he resumed his seat.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 313 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Afiliado al PT, diputado federal por São Paulo y ministro jefe de la Casa Civil hasta presentar su dimisión el 16 de junio de 2005, cuando retomó su escaño.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 313 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified by the Prosecutor General''s Office (PGR) as head of the political nucleus, he denies the accusations. The STF convicted him of active corruption, sentencing him to 7 years and 11 months, and acquitted him of criminal conspiracy (formação de quadrilha) in 2014; the sentence was extinguished by a pardon in October 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 314 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado por la Fiscalía General (PGR) como jefe del núcleo político, niega las acusaciones. El STF lo condenó por cohecho activo a 7 años y 11 meses y lo absolvió de asociación ilícita (formación de quadrilha) en 2014; la pena se extinguió por indulto en octubre de 2016.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 314 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'National president of the PT and former federal deputy for São Paulo, he left the party presidency in July 2005, a day after his brother''s aide was arrested with cash.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 315 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Presidente nacional del PT y exdiputado federal por São Paulo, dejó la presidencia del partido en julio de 2005, un día después de la detención del asesor de su hermano con dinero en efectivo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 315 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Charged as a member of the political nucleus, he was convicted of active corruption, sentenced to 4 years and 8 months, and acquitted of criminal conspiracy in 2014. The STF extinguished his liability by pardon on 4 March 2015.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 316 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Acusado como integrante del núcleo político, fue condenado por cohecho activo a 4 años y 8 meses y absuelto de asociación ilícita en 2014. El STF extinguió su responsabilidad penal por indulto el 4 de marzo de 2015.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 316 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
