INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the rapporteur, the then president Pedro Corrêa raised R$ 3 million from the scheme for the PP through the brokerage Bônus-Banval; the STF convicted Corrêa and Pedro Henry.', NULL, 'Amount attributed by Joaquim Barbosa to Pedro Corrêa for the PP', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 357 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
