INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the Prosecutor General''s Office (PGR), PMDB legislators received an improper advantage to vote with the government; the STF convicted only the former leader José Borba, of passive corruption.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 358 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la PGR, parlamentarios del PMDB recibieron una ventaja indebida para votar con el Gobierno; el STF condenó solo al exportavoz José Borba, por cohecho pasivo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 358 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Vedoin family company identified by the Federal Prosecution Service (MPF) and the Federal Police as the centre of the scheme: it won rigged tenders to sell ambulances and medical equipment to municipalities and paid bribes to legislators in exchange for amendments. The company and its owners face hundreds of criminal and administrative misconduct cases.', NULL, 'Estimate made at the time of the operation for the total moved by the group; the Office of the Comptroller General (CGU) and Denasus established a minimum loss of R$ 15.5 million; the partial CPI report counted R$ 9.46 million in bribes; the CPI''s final report speaks of more than R$ 100 million diverted.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 359 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Empresa de la familia Vedoin señalada por el MPF y la Policía Federal como centro de la trama: ganaba licitaciones amañadas para vender ambulancias y equipos médicos a ayuntamientos y pagaba sobornos a parlamentarios a cambio de enmiendas. La empresa y sus dueños responden a cientos de causas penales y por improbidad.', NULL, 'Estimación realizada en la época de la operación sobre el total movido por el grupo; la CGU y el Denasus determinaron un perjuicio mínimo de 15,5 millones de reales; el informe parcial de la CPI contabilizó 9,46 millones de reales en sobornos; el informe final de la CPI habla de más de 100 millones de reales desviados.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 359 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Requests to release the amendments were sent to the Ministry of Health, where the aide Maria da Penha Lino, according to the CPI, approved agreements and facilitated the release of funds; the CPI found no evidence of involvement by ministers José Serra, Barjas Negri, Humberto Costa and Saraiva Felipe.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 360 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Las solicitudes de liberación de las enmiendas se enviaban al Ministerio de Sanidad, donde la asesora Maria da Penha Lino, según la CPI, aprobaba convenios y facilitaba la liberación de fondos; la CPI no encontró pruebas de participación de los ministros José Serra, Barjas Negri, Humberto Costa y Saraiva Felipe.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 360 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
