INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He confessed and informed on the scheme in a plea agreement, which led to the creation of the CPI; in the main case he was convicted of criminal association, tender fraud and active corruption, but the TRF-1 declared his liability extinguished as time-barred in February 2021 and he obtained judicial pardon in other cases.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 363 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Confesó y delató la trama en un acuerdo de colaboración, que llevó a la creación de la CPI; en la causa principal fue condenado por asociación criminal, fraude en licitaciones y cohecho activo, pero el TRF-1 declaró extinguida su responsabilidad penal por prescripción en febrero de 2021 y obtuvo perdón judicial en otros procesos.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 363 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Identified as head of the scheme alongside his son, he was sentenced at first instance to 3 years and 4 months for active corruption in one of the criminal cases and, on appeal, the sentences were revised (11 years, 1 month and 10 days for active corruption after senility was recognised, which the STJ later removed, according to FolhaMax). In September 2022 Justice Gilmar Mendes (STF) recognised, at the defence''s request, time-barring of the money-laundering offence only.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 364 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Señalado como jefe de la trama junto a su hijo, fue condenado en primera instancia a 3 años y 4 meses por cohecho activo en una de las causas penales y, en segunda instancia, las penas fueron revisadas (11 años, 1 mes y 10 días por cohecho activo tras el reconocimiento de la senilidad, que el STJ retiró después, según FolhaMax). En septiembre de 2022 el ministro Gilmar Mendes (STF) reconoció, a petición de la defensa, la prescripción solo del delito de blanqueo de capitales.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 364 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'A member of the Planam group, he was ordered in January 2014 by the Federal Court in Bahia, in an administrative misconduct case, to suspension of political rights for 8 years and a ban on contracting with public bodies for 10 years; according to the MPF, all those convicted appealed.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 365 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Integrante del grupo Planam, fue condenado en enero de 2014 por la Justicia Federal de Bahía, en una acción por improbidad administrativa, a la suspensión de los derechos políticos durante 8 años y a la prohibición de contratar con el poder público durante 10 años; según el MPF, todos los condenados recurrieron.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 365 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'She worked at Planam from March 2004 to March 2005 and then took up a post at the Ministry of Health; she denies having been recommended to the ministry by the Vedoins.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 366 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Trabajó en Planam de marzo de 2004 a marzo de 2005 y después asumió un cargo en el Ministerio de Sanidad; niega haber sido recomendada por los Vedoin al ministerio.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 366 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former Ministry of Health aide accused of having been recommended by the Vedoins to facilitate the processing of amendments; she denies it, says she was used by the family and that the roughly R$ 200,000 she received related to the period she worked at Planam.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 367 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Exasesora del Ministerio de Sanidad acusada de haber sido recomendada por los Vedoin para facilitar la tramitación de las enmiendas; lo niega, afirma que fue utilizada por la familia y que los unos 200.000 reales recibidos correspondían al periodo en que trabajó en Planam.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 367 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
