INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the CPI''s partial report, he was the legislator who received the most from Planam (117 payments, 32% of the bribes) and introduced the Vedoins to other members of Congress; he faces criminal cases for corruption, laundering, fraud and criminal conspiracy, and his defence says the deposits were fundraising for election campaigns.', NULL, 'Total attributed by the CPI''s partial report (2006), rounded to whole reais in amount_brl; not an amount set in a judgment.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 369 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según el informe parcial de la CPI, fue el parlamentario que más recibió de Planam (117 pagos, el 32 % del soborno) y presentó a los Vedoin a otros congresistas; responde a procesos penales por corrupción, blanqueo, fraude y asociación ilícita, y su defensa dice que los depósitos fueron captación de fondos para campañas electorales.', NULL, 'Total atribuido por el informe parcial de la CPI (2006), redondeado a reales enteros en amount_brl; no es un importe fijado en sentencia.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 369 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Chamber''s Ethics Council unanimously approved, on 21 December 2006, an opinion in favour of stripping him of his seat, but he was not expelled because Congress went into recess the next day.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 370 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'El Consejo de Ética de la Cámara aprobó por unanimidad, el 21 de diciembre de 2006, un dictamen a favor de su destitución, pero no fue destituido porque el Congreso entró en receso al día siguiente.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 370 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
