INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The STF''s 1st Panel convicted him on 4 April 2017 of passive corruption and money laundering (12 years'' imprisonment in the closed regime, according to the Prosecutor General''s Office (PGR), which reports that the judgment was certified as final in 2017), on the basis of deposits into the accounts of an aide and his wife and Planam''s cash ledger; the defence argued that the amendments were routine and that there is no proof of receiving money, and Justice Marco Aurélio dissented on the laundering.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 375 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'La Primera Sala del STF lo condenó el 4 de abril de 2017 por cohecho pasivo y blanqueo de capitales (12 años de reclusión en régimen cerrado, según la PGR, que informa de la firmeza certificada en 2017), con base en depósitos en cuentas de un asesor y de su esposa y en el libro de caja de Planam; la defensa sostuvo que las enmiendas eran rutinarias y que no hay prueba de recepción de dinero, y el ministro Marco Aurélio discrepó en cuanto al blanqueo.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 375 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
