INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Senate Ethics Council on 28 November 2006 rejected Jefferson Péres''s report, which called for his expulsion, and approved by 12 votes to 2 only a verbal warning; he claims innocence and says he dismissed the aide on learning of the allegation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 377 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
