INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'The Federal Prosecution Service (MPF) in Mato Grosso charged him in October 2008 with criminal conspiracy, passive corruption and money laundering as part of the organisation''s political arm; according to a 2006 report, his former aide Marcelo Carvalho received R$ 225,000 from Planam to submit amendments and said he acted with the senator''s consent, and Suassuna claims innocence.', NULL, 'Amount received by the former aide according to a November 2006 report; the CPI''s list recorded R$ 222,500 for the senator; outcome of the charge not found.', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 378 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
