INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In September 2026 the Superior Electoral Court (TSE) upheld, by 5 votes to 2, the rejection of his candidacy for governor of the Federal District because he had accumulated seven collegiate convictions for wilful administrative misconduct in Operation Pandora''s Box cases (civil sphere). The defence argued that he would be eligible after the change to the Clean Record Law (Lei da Ficha Limpa) approved in 2025, since the cases were connected.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 409 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
