INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the plea-bargaining witness Paulo Roberto Costa''s testimony to Judge Sergio Moro in 2014, the PT received 3% of the value of Petrobras contracts through the Services Directorate, to go into undeclared campaign funds (caixa dois); this is an allegation by a cooperating witness. The sources read record no accusation against the party as an institution.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 450 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la declaración del delator Paulo Roberto Costa al juez Sergio Moro en 2014, el PT recibía el 3 % del valor de los contratos de Petrobras a través de la Dirección de Servicios, con destino a caja B (caixa dois) de campaña; se trata de una alegación de un colaborador. Las fuentes leídas no registran acusación contra el partido como institución.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 450 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the plea-bargaining witness Paulo Roberto Costa''s testimony to Judge Sergio Moro in 2014, the PMDB also benefited from funds diverted from Petrobras contracts; this is an allegation by a cooperating witness. The sources read record no accusation against the party as an institution.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 451 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
