INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Target, as a legal entity, of a public civil action for administrative misconduct brought by the Lava Jato task force in March 2017 in the Federal Court in Curitiba, together with ten politicians from the party; the Federal Prosecution Service (MPF) seeks repayment of R$ 460.6 million, which it attributes to bribes paid to the party and its members, as well as a civil fine and collective moral damages. This is a civil, not criminal, action; the outcome was not found and the report records no statement from the party.', NULL, 'Total sought by the MPF in the action (repayment, civil fine and collective moral damages); not an amount of conviction', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 452 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Objeto, como persona jurídica, de una acción civil pública por improbidad administrativa presentada por el grupo de trabajo de la Lava Jato en marzo de 2017 en la Justicia Federal de Curitiba, junto con diez políticos del partido; el MPF reclama el resarcimiento de 460,6 millones de reales, que atribuye a sobornos pagados al partido y a sus integrantes, además de multa civil y daños morales colectivos. Es una acción civil, no penal; no se localizó el resultado y el reportaje no registra pronunciamiento del partido.', NULL, 'Total reclamado por el MPF en la acción (resarcimiento, multa civil y daños morales colectivos); no es un importe de condena', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 452 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
