INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Firmó un acuerdo de colaboración con el MPF en agosto de 2014, homologado por el ministro Teori Zavascki (STF) el 30/09/2014; el mismo día el juez Sergio Moro le concedió prisión domiciliaria en razón de la colaboración.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 459 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Black-market currency dealer identified as the linchpin of the operation and a cooperating witness. In July 2025 Justice Dias Toffoli declared null all Lava Jato acts against him, finding that there had been collusion between the then judge Sergio Moro, the MPF and the Federal Police to pressure him to cooperate; the plea agreement was upheld. Moro called the decision an "inversion of values".', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 460 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Cambista del mercado negro señalado como pieza central de la operación y delator. En julio de 2025 el ministro Dias Toffoli declaró la nulidad de todos los actos de la Lava Jato contra él, al entender que hubo connivencia entre el entonces juez Sergio Moro, el MPF y la Policía Federal para presionarlo a colaborar; el acuerdo de colaboración se mantuvo. Moro calificó la decisión de «inversión de valores».', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 460 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'He held the Petrobras Services Directorate; in 2015 he was sentenced by Judge Sergio Moro to 20 years and 8 months for passive corruption, money laundering and criminal association.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 461 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Ocupó la Dirección de Servicios de Petrobras; en 2015 fue condenado por el juez Sergio Moro a 20 años y 8 meses por cohecho pasivo, blanqueo de capitales y asociación criminal.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 461 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted in Lava Jato in several cases for corruption and money laundering, with sentences totalling more than 39 years; he has been held in the closed regime since August 2024. On appeal to the STF''s 2nd Panel, Gilmar Mendes and Dias Toffoli voted to annul the convictions in November 2025; the judgment was not complete at the date of the report. The defence accuses the former judge Sergio Moro of collusion with prosecutors.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 462 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en la Lava Jato en varios procesos por corrupción y blanqueo de capitales, con penas que suman más de 39 años; está en prisión en régimen cerrado desde agosto de 2024. En el recurso ante la Segunda Sala del STF, Gilmar Mendes y Dias Toffoli votaron por anular las condenas en noviembre de 2025; el juicio no había concluido en la fecha del reportaje. La defensa acusa al exjuez Sergio Moro de connivencia con los fiscales.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 462 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
