INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Sentenced by Judge Sergio Moro to 16 years, 1 month and 10 days for corruption and money laundering; his plea deal was ratified by the STF in 2015, in which he named Eduardo Cunha and Renan Calheiros as beneficiaries, and he moved to house arrest. Renan and others named deny having received illicit amounts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 464 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
