INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'It signed a leniency agreement with authorities in Brazil, the United States and Switzerland in December 2016, in which it admitted taking part in unlawful acts; Odebrecht S.A.''s fine was R$ 3.828 billion, of which about R$ 3 billion went to Brazil.', NULL, 'Odebrecht S.A.''s fine under the 2016 agreement; added to Braskem''s, the total of the agreements is about R$ 6.9 billion', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 466 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
