INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police on 28/10/2026 for fraudulent management, criminal organisation and money laundering, in the partial report of Operation Compliance Zero on transactions between Master and BRB; on 04/11/2026 Justice Fachin gave the Prosecutor General''s Office (PGR) 15 days to respond on the formal naming as a suspect and, on 05/11/2026, requested an opinion on the request to revoke the pre-trial detention. The defence called the formal naming "a hasty and rash act" and argues that the detention, ordered in March, has run too long without a criminal case.', NULL, 'Estimated amount of portfolios traded without proof of underlying assets', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 644 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal el 28/10/2026 por gestión fraudulenta, organización criminal y blanqueo de capitales, en el informe parcial de la Operación Compliance Zero sobre operaciones entre el Master y el BRB; el 04/11/2026 el ministro Fachin abrió un plazo de 15 días para que la PGR se pronunciara sobre la imputación y, el 05/11/2026, pidió un dictamen sobre la solicitud de revocación de la prisión preventiva. La defensa calificó la imputación de «un acto precipitado y osado» y sostiene que la prisión, decretada en marzo, ha excedido el plazo, sin acción penal.', NULL, 'Importe estimado de carteras negociadas sin acreditación de respaldo', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 644 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
