INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In March 2025 Justice Alexandre de Moraes closed, at the request of the Prosecutor General''s Office (PGR), the investigation into vaccination-card fraud as regards Bolsonaro, for lack of evidence.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 661 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En marzo de 2025 el ministro Alexandre de Moraes archivó, a petición de la PGR, la investigación sobre el fraude en el certificado de vacunación en lo relativo a Bolsonaro, por falta de pruebas.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 661 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'In March 2026 Prosecutor General Paulo Gonet asked for the jewellery investigation to be closed, on the ground that the law does not define whether gifts received by presidents belong to the State or to the office-holder; no STF decision on the request was found.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 662 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'En marzo de 2026 el fiscal general Paulo Gonet pidió el archivo de la investigación sobre las joyas, por entender que la ley no define si los regalos recibidos por presidentes pertenecen al Estado o al mandatario; no se localizó decisión del STF sobre la petición.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 662 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'According to the STF conviction, as a former PTB leader he was responsible for political appointments to BR Distribuidora.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 663 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Según la condena del STF, como antiguo dirigente del PTB fue responsable de nombramientos políticos en BR Distribuidora.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 663 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted by the 13th Federal Court in Curitiba of passive corruption and money laundering, accused of receiving R$ 2.1 million to favour the hiring of Apolo Tubulars by Petrobras between 2009 and 2012. On 21/05/2024 the STF''s 2nd Panel, by 3 votes to 2, declared the sentence for passive corruption time-barred, without examining the merits; time-barring is not equivalent to an acquittal. The defence argued that the charges were only accepted in June 2016.', NULL, 'Bribe attributed by the prosecution; not an amount recognised in a final decision', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 665 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado por el Juzgado Federal 13.º de Curitiba por cohecho pasivo y blanqueo de capitales, acusado de recibir 2,1 millones de reales para favorecer la contratación de Apolo Tubulars por Petrobras entre 2009 y 2012. El 21/05/2024 la Segunda Sala del STF, por 3 votos a 2, declaró prescrita la pena por cohecho pasivo, sin examinar el fondo; la prescripción no equivale a una absolución. La defensa sostuvo que la acusación solo se admitió en junio de 2016.', NULL, 'Soborno atribuido por la acusación; no es un importe reconocido en una decisión firme', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 665 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former PT treasurer, he was one of the first targets of the Curitiba task force, in 2015, and was convicted. In August 2025 Justice Dias Toffoli declared null all Lava Jato acts against him, extending decisions that found collusion between the former judge Sergio Moro and prosecutors. The defence says that Moro''s conduct tainted all the cases.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 666 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Extesorero del PT, fue uno de los primeros objetivos del grupo de trabajo de Curitiba, en 2015, y llegó a ser condenado. En agosto de 2025 el ministro Dias Toffoli declaró la nulidad de todos los actos de la Lava Jato contra él, extendiendo decisiones que reconocieron connivencia entre el exjuez Sergio Moro y los fiscales. La defensa afirma que la actuación de Moro contaminó todos los procesos.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 666 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Target of Lava Jato in Curitiba. In May 2024 Justice Dias Toffoli annulled all acts of the 13th Federal Court against him; in September 2024 the STF''s 2nd Panel upheld the nullity but did not order the immediate closure of the cases, which is a matter for the competent courts.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 667 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Objeto de la Lava Jato en Curitiba. En mayo de 2024 el ministro Dias Toffoli anuló todos los actos del Juzgado Federal 13.º contra él; en septiembre de 2024 la Segunda Sala del STF mantuvo la nulidad, pero no ordenó el cierre inmediato de los procesos, cuyo análisis corresponde a los juzgados competentes.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 667 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
