INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Convicted in Lava Jato and a cooperating witness, with a plea deal ratified by the STF in 2019. Justice Dias Toffoli annulled his convictions on the basis of the former judge Sergio Moro''s bias, and in February 2025 the STF''s 2nd Panel upheld the annulment by 3 votes to 2, rejecting an appeal by the Prosecutor General''s Office (PGR).', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 669 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Condenado en la Lava Jato y delator, con colaboración homologada por el STF en 2019. El ministro Dias Toffoli anuló sus condenas por la parcialidad del exjuez Sergio Moro, y en febrero de 2025 la Segunda Sala del STF mantuvo la anulación por 3 votos a 2, rechazando un recurso de la PGR.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 669 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Agency on whose retirees'' and pensioners'' payrolls association bodies applied deductions through Technical Cooperation Agreements; according to the investigation, most were fraudulent, with forged signatures. The agreements with the bodies under investigation were suspended after the April 2025 operation.', NULL, 'Estimate by the Federal Police and the CGU of the total charged under suspicious circumstances by associations between 2019 and 2024', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 670 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Organismo en cuyas nóminas de jubilados y pensionistas entidades asociativas aplicaban descuentos mediante Acuerdos de Cooperación Técnica; según la investigación, la mayor parte eran fraudulentos, con firmas falsificadas. Los acuerdos de las entidades investigadas fueron suspendidos tras la operación de abril de 2025.', NULL, 'Estimación de la Policía Federal y la CGU del total cobrado de forma sospechosa por entidades entre 2019 y 2024', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 670 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Former Minister of Labour and Social Security; according to a Federal Police report of July 2026 that formally named 48 people as suspects in the case, he allegedly received at least R$ 550,000 in bribes to allow improper deductions. The defence rejects the accusations and says he received no financial advantage and committed no wrongdoing.', NULL, 'Amount attributed by the Federal Police; an allegation of the investigation', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 671 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
