INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'Formally named a suspect by the Federal Police in July 2026 for passive corruption, money laundering and criminal organisation; according to investigators, as attorney and as president of the INSS he failed to oversee the association bodies in exchange for monthly bribes of about R$ 250,000. He is in pre-trial detention; the defence said it has not yet had access to the report.', NULL, 'Monthly amount attributed by the Federal Police, not a total', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 672 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'es', 'Imputado por la Policía Federal en julio de 2026 por cohecho pasivo, blanqueo de capitales y organización criminal; según los investigadores, como procurador y como presidente del INSS dejó de fiscalizar entidades asociativas a cambio de sobornos mensuales de unos 250.000 reales. Está en prisión preventiva; la defensa informó de que aún no ha tenido acceso al informe.', NULL, 'Importe mensual atribuido por la Policía Federal, no un total', relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 672 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
