INSERT INTO link_translations (link_id, lang, relation, amount, amount_note, source_text) SELECT id, 'en', 'She was among the group charged by the MP-RJ in the rachadinhas case; on 16/05/2022 the TJ-RJ''s Special Panel rejected the charges against Flávio Bolsonaro, Fabrício Queiroz and 15 others, at the request of the prosecution service itself, after the STJ and the STF annulled the evidence. The decision does not prevent a new investigation.', NULL, NULL, relation || char(10) || COALESCE(amount, '') || char(10) || COALESCE(amount_note, '') FROM links WHERE id = 542 ON CONFLICT(link_id, lang) DO UPDATE SET relation = excluded.relation, amount = excluded.amount, amount_note = excluded.amount_note, source_text = excluded.source_text;
